(function () {
  var L = window.LP.cards;
  [
   {"id": "m01-k1", "m": "m01", "q": "Wie definiert JP 3-09.3 Close Air Support?", "a": "<span class=\"qt\">2. Close Air Support Overview a. CAS is air action by fixed-wing (FW) and rotary-wing (RW) aircraft against hostile targets that are in close proximity to friendly forces and requires detailed integration of each air mission with the fire and movement of those forces.</span>", "src": [["jp3093", "p. I-1"]]},
   {"id": "m01-k2", "m": "m01", "q": "Wie beschreibt AJP-3.3 CAS-Operationen?", "a": "<span class=\"qt\">(2) Close air support. CAS operations are conducted against adversary forces/military objectives that are in close proximity to friendly forces and which require detailed coordination for fire and movement, friendly fire avoidance and terminal attack control performed by joint terminal attack controllers or forward air controllers (airborne).</span>", "src": [["ajp33", "p. 28"]]},
   {"id": "m01-k3", "m": "m01", "q": "Wie beschreibt AJP-3.3 Air Interdiction?", "a": "<span class=\"qt\">(1) Air interdiction. AI operations are those conducted to dislocate, disrupt, delay, degrade or destroy an adversary’s military potential before it can be brought to bear effectively. Their distance from friendly forces is such that detailed engagement space deconfliction with the land component is not essential.</span>", "src": [["ajp33", "p. 28"]]},
   {"id": "m01-k4", "m": "m01", "q": "Was ist Terminal Attack Control (TAC)?", "a": "<span class=\"qt\">e. TAC. TAC is the authority to control the maneuver of and grant weapons release clearance to attacking aircraft. A certified and qualified joint terminal attack controller (JTAC) or forward air controller (airborne) (FAC[A]) will be recognized across the Department of Defense as capable and authorized to perform TAC.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m01-k5", "m": "m01", "q": "Was sind Terminal Guidance Operations (TGO)?", "a": "<span class=\"qt\">terminal guidance operations. Actions using electronic, mechanical, voice, or visual communications that provide approaching aircraft and/or weapons additional information regarding a specific target location. Also called TGO. (Approved for incorporation into JP 1-02.)</span>", "src": [["jp309", "p. GL-9"]]},
   {"id": "m01-k6", "m": "m01", "q": "Wie definiert JP 3-09.3 den JTAC (Glossar)?", "a": "<span class=\"qt\">joint terminal attack controller. A qualified (certified) Service member who, from a forward position, directs the action of combat aircraft engaged in close air support and other offensive air operations. Also called JTAC. (Approved for incorporation into JP 1-02.)</span>", "src": [["jp3093", "p. GL-11"]]},
   {"id": "m01-k7", "m": "m01", "q": "Wie definiert JP 3-09.3 den FAC(A) (Glossar)?", "a": "<span class=\"qt\">forward air controller (airborne). A specifically trained and qualified aviation officer, normally an airborne extension of the tactical air control party, who exercises control from the air of aircraft engaged in close air support of ground troops. Also called FAC(A). (Approved for incorporation into JP 1-02.)</span>", "src": [["jp3093", "p. GL-10"]]},
   {"id": "m01-k8", "m": "m01", "q": "Was ist ein JFO und was darf er?", "a": "<span class=\"qt\">(5) JFO. A JFO is a qualified and certified Service member who can request, adjust, and control surface-to-surface fires, provide targeting information in support of Type 2 and 3 CAS TACs, and perform TGO in conjunction with a JTAC/FAC(A).</span>", "src": [["jp3093", "p. II-10"]]},
   {"id": "m01-k9", "m": "m01", "q": "Was ist ein TAC(A)?", "a": "<span class=\"qt\">(d) TAC(A). The TAC(A) is an extension of air support control agencies. In the TACS, TAC(A) provides communications relay between the TACP and attack aircraft, as well as other agencies of the TACS, in the absence of JSTARS, or a FAC(A).</span>", "src": [["jp3093", "p. II-8"]]},
   {"id": "m01-k10", "m": "m01", "q": "Was ist der TACP?", "a": "<span class=\"qt\">(5) Tactical Air Control Party (TACP). The TACP is the principal air liaison unit collocated with ground maneuver units.</span>", "src": [["jp3093", "p. II-6"]]},
   {"id": "m01-k11", "m": "m01", "q": "Wer ist der ALO?", "a": "<span class=\"qt\">(a) ALO. The ALO is the senior TACP member attached to a ground unit who functions as the primary advisor to the ground commander on air operations. An ALO is an expert in the capabilities and limitations of air operations.</span>", "src": [["jp3093", "p. II-6"]]},
   {"id": "m01-k12", "m": "m01", "q": "Welche Bedingungen nennt JP 3-09.3 für wirksames CAS?", "a": "<span class=\"qt\">The conditions for effective CAS are: thoroughly trained personnel with well-developed skills, effective planning and integration, effective C2, air superiority (especially suppression of enemy air defenses [SEAD]), target marking and/or acquisition, streamlined and flexible procedures, and appropriate ordnance. Although not a requirement for CAS employment, favorable environmental conditions improve CAS effectiveness.</span>", "src": [["jp3093", "p. I-6"]]},
   {"id": "m02-k1", "m": "m02", "q": "Was ist die ASOC (JP 3-09.3)?", "a": "<span class=\"qt\">(4) ASOC. The ASOC is the principal air control agency within the TACS, responsible for controlling joint air operations that directly support ground forces.</span>", "src": [["jp3093", "p. II-6"]]},
   {"id": "m02-k2", "m": "m02", "q": "Was ist das ASOC laut NATO (AJP-3.3, Glossar)?", "a": "<span class=\"qt\">air support operations centre An agency of a theatre air control system collocated with a corps headquarters or an appropriate land force headquarters, which coordinates and directs close air support and other tactical air support. (NATO Agreed)</span>", "src": [["ajp33", "p. LEX-6"]]},
   {"id": "m02-k3", "m": "m02", "q": "Wofür ist das TAD-Netz da?", "a": "<span class=\"qt\">(i) TAD Net. The TAD net provides a means for the control of aircraft. TAD nets are used by all of the C2 nodes.</span>", "src": [["jp3093", "p. II-26"]]},
   {"id": "m02-k4", "m": "m02", "q": "Was ist das JARN?", "a": "<span class=\"qt\">(g) JARN. The JARN is the link between the ASOC and subordinate TACPs for aircraft coordination and sending immediate air support requests.</span>", "src": [["jp3093", "p. II-25"]]},
   {"id": "m02-k5", "m": "m02", "q": "Was regelt die ATO und für welchen Zeitraum?", "a": "<span class=\"qt\">4.15 The ATO articulates tasking for air operations for a specific time, normally 24 hours.</span>", "src": [["ajp33", "p. 44"]]},
   {"id": "m02-k6", "m": "m02", "q": "Welche zwei Arten von CAS-Anforderungen gibt es?", "a": "<span class=\"qt\">Air support requests are used to identify the supported commander’s requirements for CAS and other supporting air missions. There are two types of CAS requests: preplanned and immediate.</span>", "src": [["jp3093", "p. III-127"]]},
   {"id": "m02-k7", "m": "m02", "q": "Was ist eine Preplanned Request?", "a": "<span class=\"qt\">a. Preplanned Requests. Those CAS requirements foreseen early enough to be included in the first ATO distribution are submitted as preplanned air support requests for CAS.</span>", "src": [["jp3093", "p. III-128"]]},
   {"id": "m02-k8", "m": "m02", "q": "Woraus entstehen Immediate Requests?", "a": "<span class=\"qt\">b. Immediate Air Support Requests. Immediate air support requests arise from situations that develop outside the planning stages of the joint air tasking cycle.</span>", "src": [["jp3093", "p. III-129"]]},
   {"id": "m02-k9", "m": "m02", "q": "Was bedeutet Schweigen einer Zwischenebene bei einer Immediate Request?", "a": "<span class=\"qt\">Silence by intermediate HQ implies consent to the request.</span>", "src": [["jp3093", "p. III-130"]]},
   {"id": "m02-k10", "m": "m02", "q": "Mit welchem Formular wird CAS angefordert?", "a": "<span class=\"qt\">(5) Request Format. The JTAR (DD 1972) is used for requesting CAS through the ASOC/DASC.</span>", "src": [["jp3093", "p. III-131"]]},
   {"id": "m03-k1", "m": "m03", "q": "Wie ist der CAS-Entscheidungsprozess aufgebaut?", "a": "<span class=\"qt\">The CAS decision-making process, as indicated in Figure III-1, is a continuous three-phase cycle that has been tailored for joint fire support and focused specifically on CAS.</span>", "src": [["jp3093", "p. III-1"]]},
   {"id": "m03-k2", "m": "m03", "q": "Was ist Battle Tracking?", "a": "<span class=\"qt\">a. Battle Tracking. Battle tracking is the process of building and maintaining an overall picture of the operational environment that is accurate, timely, and relevant.</span>", "src": [["jp3093", "p. III-32"]]},
   {"id": "m03-k3", "m": "m03", "q": "Wozu dienen Risk-Estimate Distances?", "a": "<span class=\"qt\">(10) Risk Estimate Distance (a) Risk estimate distances allow the supported commander to estimate the potential danger to friendly troops from the CAS attack. They are discussed as 0.1 percent probability of incapacitation (Pi) (i.e., 1 in 1,000 Pi).</span>", "src": [["jp3093", "p. III-36"]]},
   {"id": "m03-k4", "m": "m03", "q": "Wann ist CAS „danger close“ und wer trägt die Verantwortung?", "a": "<span class=\"qt\">(b) Danger Close. Ordnance delivery inside the 0.1 percent Pi distance will be considered “danger close.” The supported commander must accept responsibility for the risk to friendly forces when targets are inside the 0.1 percent Pi distance.</span>", "src": [["jp3093", "p. III-37"]]},
   {"id": "m03-k5", "m": "m03", "q": "Was ist Combat Identification?", "a": "<span class=\"qt\">combat identification. The process of attaining an accurate characterization of detected objects in the operational environment sufficient to support an engagement decision. Also called CID. (JP 1-02. SOURCE: JP 3-09)</span>", "src": [["jp309", "p. GL-6"]]},
   {"id": "m03-k6", "m": "m03", "q": "Was ist Positive Identification (PID)?", "a": "<span class=\"qt\">3-92. Positive identification is reasonable certainty that the entity or object is a valid military target and the correct target. The entity or target must demonstrate a hostile act, intent, or be on the approved list of targets.</span>", "src": [["atp30930", "p. 3-24"]]},
   {"id": "m03-k7", "m": "m03", "q": "Was gehört zur Vorbereitung (Preparation)?", "a": "<span class=\"qt\">d. Preparation includes COE briefs, COE mission rehearsals, OPORDs, brief-backs, equipment and communications checks, SOP reviews, load plan verification, pre-combat checks/pre-combat inspections, and weapons test-fire.</span>", "src": [["jp3093", "p. IV-1"]]},
   {"id": "m03-k8", "m": "m03", "q": "Wer macht laufend taktische Risikobewertungen?", "a": "<span class=\"qt\">d. Tactical Risk Assessment. In addition to proper battle tracking, the supported commander and staff make continuous tactical risk assessments.</span>", "src": [["jp3093", "p. III-35"]]},
   {"id": "m04-k1", "m": "m04", "q": "Wann wird Type 1 Control verwendet?", "a": "<span class=\"qt\">(1) Type 1 Control. Type 1 control is used when the JTAC/FAC(A) requires control of individual attacks and the situation requires the JTAC/FAC(A) to visually acquire the attacking aircraft and visually acquire the target for each attack.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m04-k2", "m": "m04", "q": "Wann wird Type 2 Control verwendet?", "a": "<span class=\"qt\">(2) Type 2 Control. Type 2 control is used when the JTAC/FAC(A) requires control of individual attacks and is unable to visually acquire the attacking aircraft at weapons release or is unable to visually acquire the target.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m04-k3", "m": "m04", "q": "Wann wird Type 3 Control verwendet?", "a": "<span class=\"qt\">(3) Type 3 Control. Type 3 control is used when the JTAC/FAC(A) requires the ability to provide clearance for multiple attacks within a single engagement subject to specific attack restrictions.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m04-k4", "m": "m04", "q": "Was ist die Method of Attack und wovon ist sie unabhängig?", "a": "<span class=\"qt\">b. Methods of Attack. The method of attack and type of control are separate and independent constructs. The method of attack is an agreement between the supported commander, the JTAC/FAC(A), and the aircraft, regarding the aircrew’s correlation requirement, and is completely independent of the type of control.</span>", "src": [["jp3093", "p. III-47"]]},
   {"id": "m04-k5", "m": "m04", "q": "Was ist Korrelation und wie oft ist sie nötig?", "a": "<span class=\"qt\">In CAS, correlation is the process by which the JTAC/FAC(A) coordinates and confirms that the attacking aircrew, and/or a third-party contributor, have acquired the correct target or mark. Correlation is required on each and every CAS attack.</span>", "src": [["jp3093", "p. III-47"]]},
   {"id": "m04-k6", "m": "m04", "q": "Wann wird BOC verwendet?", "a": "<span class=\"qt\">(2) A BOC attack is used when the JTAC/FAC(A) determines that the desired effects can be created against the target with CAS aircraft employing ordnance on a specified set of coordinates. The coordinates must be of sufficient fidelity/mensuration to produce the desired effect on the target and be used for fires approval.</span>", "src": [["jp3093", "p. III-48"]]},
   {"id": "m04-k7", "m": "m04", "q": "Was verlangt ein BOT-Angriff?", "a": "<span class=\"qt\">(3) A BOT attack requires that the JTAC/FAC(A)’s intended target or mark is TALLY/CONTACT/CAPTURED by the aircrew. Coordinate accuracy and precision (to include TLE) are not as important as the JTAC’s/FAC(A)’s ability to aid CAS aircraft in acquiring the target.</span>", "src": [["jp3093", "p. III-49"]]},
   {"id": "m04-k8", "m": "m04", "q": "Wer liest bei BOT bzw. BOC Line 4 und Line 6 zurück?", "a": "<span class=\"qt\">(a) For BOT missions, only the lead aircraft is required to read back Line 4 and Line 6, in conjunction with other required restrictions. All attack aircraft will conduct readbacks if requested by the JTAC/ FAC(A).<br><br>(b) For BOC missions, all aircraft delivering ordnance must read back Line 4 and Line 6 from their system or weapon, as appropriate, in conjunction with other required restrictions.</span>", "src": [["jp3093", "p. III-48"]]},
   {"id": "m04-k9", "m": "m04", "q": "Was bedeutet ABORT und wann wird es verwendet?", "a": "<span class=\"qt\">(1) ABORT. Term used by a JTAC/FAC(A) during all types of control to terminate the attack prior to weapons release.</span>", "src": [["jp3093", "p. III-40"]]},
   {"id": "m04-k10", "m": "m04", "q": "Was ist ein Post-Launch Abort (PLA)?", "a": "<span class=\"qt\">post-launch abort. Deliberate action taken post-separation to cause a precision munition to miss its target. Also called PLA. (Approved for inclusion in JP 1-02.)</span>", "src": [["jp3093", "p. GL-12"]]},
   {"id": "m04-k11", "m": "m04", "q": "Wann gibt der JTAC die Type of Control und Method of Attack bekannt?", "a": "<span class=\"qt\">(2) JTACs/FAC(A)s will provide the type of control and method of attack as part of the game plan.</span>", "src": [["jp3093", "p. III-50"]]},
   {"id": "m05-k1", "m": "m05", "q": "Wozu dient das CAS Execution Template?", "a": "<span class=\"qt\">b. CAS Execution Template. By its very nature, the execution of CAS differs in every tactical situation. The following considerations and recommendations are meant to be a guide for execution of CAS, so that both CAS aircrew and JTACs have a standard, repeatable format to expect in the highly dynamic CAS environment.</span>", "src": [["jp3093", "p. V-14"]]},
   {"id": "m05-k2", "m": "m05", "q": "Was muss der JTAC neu eingecheckten Luftfahrzeugen sofort mitteilen?", "a": "<span class=\"qt\">(1) Routing/Safety of Flight. JTAC/FAC(A) should immediately advise newly checked-in aircraft of other AOS, their call sign, operating altitude, and frequency, as soon as possible.</span>", "src": [["jp3093", "p. V-14"]]},
   {"id": "m05-k3", "m": "m05", "q": "Warum ist der Check-in wichtig?", "a": "<span class=\"qt\">(2) CAS Aircraft Check-In. Aircraft check-in procedures are essential for establishing the required flow of information between the CAS aircrews and control agencies.</span>", "src": [["jp3093", "p. V-15"]]},
   {"id": "m05-k4", "m": "m05", "q": "Was ist das Situation Update?", "a": "<span class=\"qt\">(3) Situation Update (a) The situation update brief is a tool used to increase all players’ SA to the level required by the tactical situation.</span>", "src": [["jp3093", "p. V-17"]]},
   {"id": "m05-k5", "m": "m05", "q": "Was ist der Game Plan und was muss er mindestens enthalten?", "a": "<span class=\"qt\">(4) Game Plan. A concise means to inform all players of the flow of the upcoming attack. Minimum information shall include type of control and method of attack.</span>", "src": [["jp3093", "p. V-20"]]},
   {"id": "m05-k6", "m": "m05", "q": "Müssen beim Situation Update alle Zeilen übermittelt werden?", "a": "<span class=\"qt\">(b) Only those lines that apply should be passed.</span>", "src": [["jp3093", "p. V-20"]]},
   {"id": "m05-k7", "m": "m05", "q": "Was bedeutet Sequential Timing?", "a": "<span class=\"qt\">2. Sequential Timing. Aircraft will attack one at a time with a specific interval between each aircraft.</span>", "src": [["jp3093", "p. V-5"]]},
   {"id": "m05-k8", "m": "m05", "q": "Wie kann der JTAC den CAS Brief ankündigen?", "a": "<span class=\"qt\">(b) CAS brief can be prefaced by: “Razor 53, advise when ready for 9-line.”</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-k1", "m": "m06", "q": "Welche Lines sind beim 9-Line Pflicht-Readback?", "a": "<span class=\"qt\">(7) Readbacks (a) Required readbacks of lines 4, 6, and restrictions.</span>", "src": [["jp3093", "p. V-33"]]},
   {"id": "m06-k2", "m": "m06", "q": "Was gilt laut Fig. V-9 für Line-Nummern und Maßeinheiten?", "a": "<span class=\"qt\">Do not transmit line numbers. Units of measure are standard unless briefed.</span>", "src": [["jp3093", "p. V-25"]]},
   {"id": "m06-k3", "m": "m06", "q": "Was ist Line 1 (IP oder BP)?", "a": "<span class=\"qt\">(d) Line 1–IP or BP. The IP is the starting point for the run-in to the target. For RW aircraft, the BP is where attacks on the target are commenced.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-k4", "m": "m06", "q": "Was wird in Line 2 übermittelt?", "a": "<span class=\"qt\">(e) Line 2―Heading and Offset. The heading is given in degrees magnetic from the IP to the target or from the center of the BP to the target.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-k5", "m": "m06", "q": "Wie wird Line 3 (Distance) angegeben?", "a": "<span class=\"qt\">(f) Line 3―Distance. The distance is given from the IP/BP to the target. For fixed wing aircraft, the distance is given in nautical miles and should be accurate to a tenth of a nautical mile.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-k6", "m": "m06", "q": "In welcher Einheit wird die Zielhöhe (Line 4) angegeben?", "a": "<span class=\"qt\">(g) Line 4―Target Elevation. The target elevation is given in feet MSL.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-k7", "m": "m06", "q": "Wie soll die Zielbeschreibung (Line 5) sein?", "a": "<span class=\"qt\">(h) Line 5―Target Description. The target description should be specific enough for the aircrew to recognize the target.</span>", "src": [["jp3093", "p. V-27"]]},
   {"id": "m06-k8", "m": "m06", "q": "Wie wird Line 8 übermittelt?", "a": "<span class=\"qt\">(k) Line 8-Friendlies. Cardinal/sub-cardinal heading from the target (N, NE, E, SE, S, SW, W, or NW) and distance of closest friendly position from the target in meters (e.g., “South 300”).</span>", "src": [["jp3093", "p. V-30"]]},
   {"id": "m06-k9", "m": "m06", "q": "Was verlangt die NATO-ATP zu Line 8?", "a": "<span class=\"qt\">Note: NATO Allied Tactical Publication 3.3.2.1, TTP for Close Air Support and Air Interdiction, requires Line 8 to be a mandatory readback item. When working with NATO FACs/JTACs, aircrew should be prepared to read back Line 8 as part of the mandatory readback items.</span>", "src": [["jp3093", "p. V-30"]]},
   {"id": "m06-k10", "m": "m06", "q": "Was verlangt die NATO-ATP zu den Line-Titeln?", "a": "<span class=\"qt\">Note: Allied Tactical Publication 3.3.2.1, TTP for Close Air Support and Air Interdiction, directs that NATO FACs will pass line titles for each line in a CAS brief.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-k11", "m": "m06", "q": "Was ist Line 9 (Egress)?", "a": "<span class=\"qt\">(l) Line 9-Egress. These are the instructions the aircrews use to exit the target area. Egress instructions can be given as a cardinal direction by using control points or, if the operational environment allows, by stating “Egress at pilot’s discretion.”</span>", "src": [["jp3093", "p. V-30"]]},
   {"id": "m06-k12", "m": "m06", "q": "Was gilt immer als Restriction?", "a": "<span class=\"qt\">(b) If issued, FAHs, ACAs, danger close, and TOTs shall always be considered restrictions and will be read back.</span>", "src": [["jp3093", "p. V-33"]]},
   {"id": "m07-k1", "m": "m07", "q": "Was ist Korrelation (Execution)?", "a": "<span class=\"qt\">(8) Correlation. The process by which the JTAC/FAC(A) coordinates and confirms that the attacking aircraft and/or a third party contributor have acquired the correct target or mark.</span>", "src": [["jp3093", "p. V-34"]]},
   {"id": "m07-k2", "m": "m07", "q": "Wann soll eine Zielmarkierung gegeben werden?", "a": "<span class=\"qt\">(a) Marks. A target mark should be provided for CAS aircraft whenever needed. Target marks should be planned to include sufficient time for CAS aircrews to observe them prior to employment.</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-k3", "m": "m07", "q": "Was bedeutet TALLY?", "a": "<span class=\"qt\">TALLY Sighting of a target, nonfriendly aircraft, or enemy position. Opposite of NO JOY.</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-k4", "m": "m07", "q": "Was bedeutet CONTACT?", "a": "<span class=\"qt\">CONTACT Acknowledges sighting of a specified reference point (either visually or via sensor).</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-k5", "m": "m07", "q": "Was bedeutet VISUAL?", "a": "<span class=\"qt\">VISUAL Sighting of a FRIENDLY aircraft or ground position. Opposite of BLIND.</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-k6", "m": "m07", "q": "Wofür steht FIDO beim Talk-on?", "a": "<span class=\"qt\">i. Talk-on descriptions and directions should be simple and short, driving the aircrew’s eyes and/or sensors from one point to another. A technique for doing this is to give directions in the following format, known by the mnemonic, “FIDO”:<br><br>(1) From a point (easily recognizable start point).<br><br>(2) In a direction (cardinal/sub-cardinal direction).<br><br>(3) Distance to travel (established unit of measure or meters).<br><br>(4) Object seen (target or object the JTAC/FAC[A] wants the aircrew to see).</span>", "src": [["jp3093", "p. V-43"]]},
   {"id": "m07-k7", "m": "m07", "q": "Welches Verhältnis empfiehlt JP 3-09.3 beim Talk-on?", "a": "<span class=\"qt\">o. A two-to-one ratio should be used when conducting talk-ons. Give two directive statements, then ask a confirming question of the aircrew.</span>", "src": [["jp3093", "p. V-44"]]},
   {"id": "m07-k8", "m": "m07", "q": "Warum darf FMV nicht alleinige Zielidentifizierung sein?", "a": "<span class=\"qt\">FMV feeds should not be used as a single-source target identification method.</span>", "src": [["jp3093", "p. III-118"]]},
   {"id": "m07-k9", "m": "m07", "q": "Wie bewegt man beim VDL-Talk-on mit SLEW den Sensor?", "a": "<span class=\"qt\">e. When using the term SLEW to directively move a sensor, JTACs should use up, down, left, and right instead of cardinal directions, to avoid confusion.</span>", "src": [["jp3093", "p. V-45"]]},
   {"id": "m08-k1", "m": "m08", "q": "Was darf eine Besatzung nie allein auf einen LST stützen?", "a": "<span class=\"qt\">WARNING Aircrews shall not use LSTs as the sole source for target identification.</span>", "src": [["jp3093", "p. III-54"]]},
   {"id": "m08-k2", "m": "m08", "q": "Was muss ein LST mit dem LTD gemeinsam haben?", "a": "<span class=\"qt\">(c) LST. LSTs must be set to the same code as the coded LTD for the user to see the target being lased.</span>", "src": [["jp3093", "p. III-56"]]},
   {"id": "m08-k3", "m": "m08", "q": "Welchen Laser-Code verwendet der JTAC?", "a": "<span class=\"qt\">The JTAC/FAC(A) will use the laser code passed by aircrew set in any LGWs they briefed during the CAS check-in briefing.</span>", "src": [["jp3093", "p. III-79"]]},
   {"id": "m08-k4", "m": "m08", "q": "Was bedeutet TEN SECONDS?", "a": "<span class=\"qt\">TEN SECONDS Standby for LASER ON call in approximately 10 seconds.</span>", "src": [["jp3093", "p. III-79"]]},
   {"id": "m08-k5", "m": "m08", "q": "Was bedeutet SPOT?", "a": "<span class=\"qt\">SPOT Acquisition of laser designation</span>", "src": [["jp3093", "p. III-79"]]},
   {"id": "m08-k6", "m": "m08", "q": "Was bedeutet SPARKLE?", "a": "<span class=\"qt\">SPARKLE Mark/marking target by infrared (IR) pointer.</span>", "src": [["jp3093", "p. III-80"]]},
   {"id": "m08-k7", "m": "m08", "q": "Was bedeutet ROPE und welche Warnung gilt?", "a": "<span class=\"qt\">ROPE Circling an IR pointer around an aircraft to help the aircraft identify the friendly ground position. Caution: This technique may damage night vision devices.</span>", "src": [["jp3093", "p. III-80"]]},
   {"id": "m08-k8", "m": "m08", "q": "Worauf beruhen IAMs?", "a": "<span class=\"qt\">b. IAMs. These weapons rely on a self-contained GPS-aided INS, which guides the weapon from the release point to target coordinates regardless of weather, camouflage, or obscurants.</span>", "src": [["jp3093", "p. III-61"]]},
   {"id": "m08-k9", "m": "m08", "q": "Was ist LOBL?", "a": "<span class=\"qt\">1. LOBL is when the missile seeker locks onto properly coded laser energy prior to the missile launch.</span>", "src": [["jp3093", "p. III-60"]]},
   {"id": "m08-k10", "m": "m08", "q": "Darf die Besatzung übermittelte Koordinaten für IAMs anpassen?", "a": "<span class=\"qt\">Aircrew will not adjust coordinates that are passed and put into the system for any reason.</span>", "src": [["jp3093", "p. III-62"]]},
   {"id": "m09-k1", "m": "m09", "q": "Was ist TLE?", "a": "<span class=\"qt\">target location error. The difference between the coordinates generated for a target and the actual location of the target. Also called TLE. (Approved for incorporation into JP 1- 02.)</span>", "src": [["jp3093", "p. GL-13"]]},
   {"id": "m09-k2", "m": "m09", "q": "Was ist Mensuration?", "a": "<span class=\"qt\">(c) Target coordinate mensuration is the process of measurement of a feature or location on the Earth to determine an absolute latitude, longitude, and height.</span>", "src": [["jp3093", "p. III-33"]]},
   {"id": "m09-k3", "m": "m09", "q": "Welcher Höhenbezug gilt standardmäßig für die Zielhöhe?", "a": "<span class=\"qt\">(a) Target Elevation (Line 4). The default target elevation is in ft MSL.</span>", "src": [["jp3093", "p. V-1"]]},
   {"id": "m09-k4", "m": "m09", "q": "Was muss gesagt werden, wenn nicht MSL verwendet wird?", "a": "<span class=\"qt\">2. MSL is understood; if using any other datum, it must be stated, e.g., “Three six five feet height above ellipsoid.”</span>", "src": [["jp3093", "p. V-27"]]},
   {"id": "m09-k5", "m": "m09", "q": "Was ist ein Mil (Strich)?", "a": "<span class=\"qt\">3-20. A mil is a unit of measure for angles that is based on the angle subtended by l/6400 of the circumference of a circle (TC 3-09.81).</span>", "src": [["atp30930", "p. 3-3"]]},
   {"id": "m09-k6", "m": "m09", "q": "Was ist der Observer-Target Factor?", "a": "<span class=\"qt\">3-26. The observer-target factor is the distance in meters from the observer to the target expressed to the nearest thousand and in thousands.</span>", "src": [["atp30930", "p. 3-5"]]},
   {"id": "m09-k7", "m": "m09", "q": "Was ist der Azimut?", "a": "<span class=\"qt\">3-17. Azimuth is a horizontal angle measured clockwise from a north base line that could be true north, magnetic north, or grid north.</span>", "src": [["atp30930", "p. 3-3"]]},
   {"id": "m09-k8", "m": "m09", "q": "Was sagt die Anzahl der Ziffern einer Gitterkoordinate aus?", "a": "<span class=\"qt\">4. The number of digits in a grid coordinate is the level of precision of the grid, not a measurement of accuracy.</span>", "src": [["jp3093", "p. V-28"]]},
   {"id": "m10-k1", "m": "m10", "q": "Was ist eine ACA?", "a": "<span class=\"qt\">airspace coordination area. A three-dimensional block of airspace in a target area, established by the appropriate commander, in which friendly aircraft are reasonably safe from friendly surface fires. Also called ACA. (Approved for incorporation into JP 1- 02.)</span>", "src": [["jp3093", "p. GL-8"]]},
   {"id": "m10-k2", "m": "m10", "q": "Was ist eine FSCL?", "a": "<span class=\"qt\">fire support coordination line. A fire support coordination measure established by the land or amphibious force commander to support common objectives within an area of operation; beyond which all fires must be coordinated with affected commanders prior to engagement, and short of the line, all fires must be coordinated with the establishing commander prior to engagement. Also called FSCL. (Approved for incorporation into JP 1-02.)</span>", "src": [["jp309", "p. GL-7"]]},
   {"id": "m10-k3", "m": "m10", "q": "Was ist eine NFA?", "a": "<span class=\"qt\">no-fire area. An area designated by the appropriate commander into which fires or their effects are prohibited. Also called NFA. (JP 1-02. SOURCE: JP 3-09.3)</span>", "src": [["jp3093", "p. GL-12"]]},
   {"id": "m10-k4", "m": "m10", "q": "Was ist eine RFL?", "a": "<span class=\"qt\">restrictive fire line. A line established between converging friendly surface forces that prohibits fires or their effects across that line. Also called RFL. (JP 1-02. SOURCE: JP 3- 09)</span>", "src": [["jp309", "p. GL-9"]]},
   {"id": "m10-k5", "m": "m10", "q": "Was ist eine CFL?", "a": "<span class=\"qt\">coordinated fire line. A line beyond which conventional surface-to-surface direct fire and indirect fire support means may fire at any time within the boundaries of the establishing headquarters without additional coordination. Also called CFL. (Approved for incorporation into JP 1-02.)</span>", "src": [["jp309", "p. GL-6"]]},
   {"id": "m10-k6", "m": "m10", "q": "Was ist eine FFA?", "a": "<span class=\"qt\">free-fire area. A specific area into which any weapon system may fire without additional coordination with the establishing headquarters. Also called FFA. (JP 1-02. SOURCE: JP 3-09)</span>", "src": [["jp309", "p. GL-8"]]},
   {"id": "m10-k7", "m": "m10", "q": "Was ist TOT?", "a": "<span class=\"qt\">time on target. The actual time at which munitions impact the target. Also called TOT. (JP 1-02. SOURCE: JP 3-09.3)</span>", "src": [["jp3093", "p. GL-14"]]},
   {"id": "m10-k8", "m": "m10", "q": "Was ist TTT?", "a": "<span class=\"qt\">time to target. The number of minutes and seconds to elapse before aircraft ordnance impacts on target. Also called TTT. (JP 1-02. SOURCE: JP 3-09.3)</span>", "src": [["jp3093", "p. GL-14"]]},
   {"id": "m10-k9", "m": "m10", "q": "Was sagt die Offset Direction der Besatzung?", "a": "<span class=\"qt\">(c) Offset Direction. The offset direction tells the aircrew on which side of the IP-to-target line they can maneuver for the attack (see Figure III-19).</span>", "src": [["jp3093", "p. III-75"]]},
   {"id": "m10-k10", "m": "m10", "q": "Warum werden Final Attack Headings vergeben?", "a": "<span class=\"qt\">(d) Final Attack Headings. JTACs/FAC(A)s assign attack headings for several reasons: to increase ground troop safety, aid in aircraft acquisition by the JTAC/FAC(A), aid aircrews in target acquisition, mitigate collateral damage, meet laser safety cone attack restrictions, and facilitate fire support coordination.</span>", "src": [["jp3093", "p. III-76"]]},
   {"id": "m10-k11", "m": "m10", "q": "Was ist der Keyhole Template?", "a": "<span class=\"qt\">1. Keyhole template is an efficient method for establishing an IP in the absence of control points or when their location does not sufficiently support target engagement (see Figure III-18).</span>", "src": [["jp3093", "p. III-74"]]},
   {"id": "m10-k12", "m": "m10", "q": "Was ist das primäre Ziel von SEAD?", "a": "<span class=\"qt\">1. The primary objective of SEAD is to allow friendly aircraft to operate in airspace defended by an enemy air defense system, including the target area and ingress/egress routes. SEAD missions do not guarantee aircraft immunity from enemy air defenses.</span>", "src": [["jp3093", "p. III-81"]]},
   {"id": "m11-k1", "m": "m11", "q": "Was ist ein Call for Fire?", "a": "<span class=\"qt\">4-1. A call for fire is a request for fire containing data necessary for obtaining the required fire on a target (FM 3-09).</span>", "src": [["atp30930", "p. 4-1"]]},
   {"id": "m11-k2", "m": "m11", "q": "Welche sechs Elemente hat ein Call for Fire?", "a": "<span class=\"qt\">4-8. The six elements of a call for fire include: observer identification, warning order, target location, target description, method of engagement and method of fire and control. Regardless of the method of target location used, the call for fire is normally sent in three transmissions, consisting of six elements, with a break and read back after each transmission.</span>", "src": [["atp30930", "p. 4-2"]]},
   {"id": "m11-k3", "m": "m11", "q": "Was enthält die Warning Order?", "a": "<span class=\"qt\">4-10. The warning order clears the net for the fire mission. The warning order consists of the type of mission, the size of the element to fire for effect, and the method of target location.</span>", "src": [["atp30930", "p. 4-2"]]},
   {"id": "m11-k4", "m": "m11", "q": "Welche Mission Types gibt es in der Warning Order?", "a": "<span class=\"qt\">4-11. The warning order begins with one of the following mission types: adjust fire, fire for effect, suppress, immediate suppression or immediate smoke.</span>", "src": [["atp30930", "p. 4-2"]]},
   {"id": "m11-k5", "m": "m11", "q": "Wann ist ein Feuerauftrag DANGER CLOSE (Steilfeuer)?", "a": "<span class=\"qt\">4-34. DANGER CLOSE is included in the method of engagement when the target is (or rounds will impact) within 600 meters of any friendly troops for mortars and artillery, 750 meters for 5 inch naval guns and tomahawk land attack missile (also TLAM). DANGER CLOSE and risk estimate distances are different in meaning.</span>", "src": [["atp30930", "p. 4-5"]]},
   {"id": "m11-k6", "m": "m11", "q": "Was bewirkt CHECK FIRING?", "a": "<span class=\"qt\">4-59. Use CHECK FIRING to cause an immediate halt in firing.</span>", "src": [["atp30930", "p. 4-8"]]},
   {"id": "m11-k7", "m": "m11", "q": "Wann sendet die FDC SPLASH?", "a": "<span class=\"qt\">4-63. Send SPLASH at the observer's request. The FDC announces SPLASH to the observer 5 seconds prior to round impact.</span>", "src": [["atp30930", "p. 4-8"]]},
   {"id": "m11-k8", "m": "m11", "q": "Wie berechnet man die Seitenkorrektur?", "a": "<span class=\"qt\">5-13. The distance, in meters, the burst is to be moved (right or left) is determined by multiplying the observer's deviation spotting in mils by the observer-target (OT) distance in thousands of meters (the observer- target factor). Express deviation corrections to the nearest 10 meters.</span>", "src": [["atp30930", "p. 5-5"]]},
   {"id": "m11-k9", "m": "m11", "q": "Wie wird eine Seitenkorrektur angesagt?", "a": "<span class=\"qt\">5-16. Announce the computed deviation correction to the FDC as LEFT (or RIGHT) (so much). The correction is opposite the spotting.</span>", "src": [["atp30930", "p. 5-5"]]},
   {"id": "m11-k10", "m": "m11", "q": "Welche Korrekturen nutzt man bei Danger Close (Creeping Fire)?", "a": "<span class=\"qt\">5-51. Use the creeping fire method of adjustment during danger close missions. The observer should make range changes by creeping the rounds to the target, using corrections of 100 meters or less, rather than making large range corrections.</span>", "src": [["atp30930", "p. 5-12"]]},
   {"id": "m11-k11", "m": "m11", "q": "Worauf muss sich Line 8 im JFO Target Brief beziehen?", "a": "<span class=\"qt\">2. JFOs shall ensure that Line 8 references the closest friendlies to the target, which may or may not be their position.</span>", "src": [["jp3093", "p. V-64"]]},
   {"id": "m11-k12", "m": "m11", "q": "Darf der JFO CLEARED HOT geben?", "a": "<span class=\"qt\">(3) While the JFO will not issue weapons release authority (i.e., CLEARED HOT), informing him of weapons release from the aircraft allows the JFO time to notify ground forces to seek cover if required.</span>", "src": [["jp3093", "p. V-67"]]},
   {"id": "m12-k1", "m": "m12", "q": "Ab welcher Höhe gelten Medium/High Altitude Tactics?", "a": "<span class=\"qt\">(2) Medium/High Altitude Tactics. Medium/high altitude tactics are flown above approximately 8,000 ft AGL. High altitude bombing can be described as bombing with the height of release over 15,000 ft AGL.</span>", "src": [["jp3093", "p. III-84"]]},
   {"id": "m12-k2", "m": "m12", "q": "Welche Höhenbänder gelten für Drehflügler?", "a": "<span class=\"qt\">(a) High. Above 3,000 ft AGL.<br><br>(b) Medium. 500-to-3,000 ft AGL.<br><br>(c) Low. Below 500 ft AGL.</span>", "src": [["jp3093", "p. III-90"]]},
   {"id": "m12-k3", "m": "m12", "q": "Wer muss Reattacks genehmigen?", "a": "<span class=\"qt\">2. The JTAC/FAC(A) must approve reattacks (after coordination with the ground force commander).</span>", "src": [["jp3093", "p. III-82"]]},
   {"id": "m12-k4", "m": "m12", "q": "Wer hat beim Abflug Vorrang?", "a": "<span class=\"qt\">1. Aircraft egressing from the target have the right-of-way.</span>", "src": [["jp3093", "p. III-82"]]},
   {"id": "m12-k5", "m": "m12", "q": "Was ist der RW CAS 5-Line?", "a": "<span class=\"qt\">16. Rotary-Wing Close Air Support 5-Line a. The RW CAS 5-line brief (Figure III-27) is a “friendly-centric” brief that is used to quickly orient RW CAS assets to a target.</span>", "src": [["jp3093", "p. III-94"]]},
   {"id": "m12-k6", "m": "m12", "q": "Ist der 5-Line eine Freigabe zum Feuern?", "a": "<span class=\"qt\">5-line briefs is that the RW CAS 5-line is still considered a CAS brief, and transmission of the brief itself does not constitute clearance to fire. This shall be made clear by a type of control and method of attack clearly stated in the game plan, prior to the 5-line.</span>", "src": [["jp3093", "p. III-95"]]},
   {"id": "m12-k7", "m": "m12", "q": "Was gehört beim 5-Line zum Readback?", "a": "<span class=\"qt\">(6) Readbacks for a RW CAS 5-line should include all restrictions.</span>", "src": [["jp3093", "p. III-96"]]},
   {"id": "m12-k8", "m": "m12", "q": "Was ist eine Show of Force?", "a": "<span class=\"qt\">A show of force is an operation designed to demonstrate resolve that involves increased visibility of deployed forces in an attempt to defuse a specific situation.</span>", "src": [["jp3093", "p. III-108"]]},
   {"id": "m12-k9", "m": "m12", "q": "Was ist DACAS?", "a": "<span class=\"qt\">(1) DACAS. The machine-to-machine exchange of required CAS mission data (e.g., aircraft check-in, CAS brief, BDA) between JTAC (or FAC[A]) and CAS platform (or C2 node) for the purpose of attacking a surface target.</span>", "src": [["jp3093", "p. III-114"]]},
   {"id": "m12-k10", "m": "m12", "q": "Welche zwei DACAS-Warnungen nennt JP 3-09.3?", "a": "<span class=\"qt\">–Presence or lack of digital information does not substitute or constitute clearance; and, –Digital track quality (the displayed value of the system's confidence of the quality of the track) does not necessarily indicate location error (e.g., target location error).</span>", "src": [["jp3093", "p. III-114"]]},
   {"id": "m13-k1", "m": "m13", "q": "Wann muss der JTAC einen Angriff abbrechen?", "a": "<span class=\"qt\">(g) Abort Procedures. The JTAC/FAC(A) shall direct CAS aircrews to abort if they are not aligned with the correct target, and must abort them if it appears that friendly troops may be endangered, or for the safety of the CAS aircrew.</span>", "src": [["jp3093", "p. V-47"]]},
   {"id": "m13-k2", "m": "m13", "q": "Wie wird ohne Abort Code abgebrochen?", "a": "<span class=\"qt\">If no abort code was briefed, then the CAS attack is aborted by simply transmitting: ABORT, ABORT, ABORT (see Figure V-11).</span>", "src": [["jp3093", "p. V-47"]]},
   {"id": "m13-k3", "m": "m13", "q": "Wer darf jederzeit ABORT rufen?", "a": "<span class=\"qt\">1. Once an aircraft calls IN, all other calls should be held until after the JTAC has issued weapons-release authority or an abort. An exception to this is that anyone can and should call an abort at any time they deem necessary.</span>", "src": [["jp3093", "p. V-46"]]},
   {"id": "m13-k4", "m": "m13", "q": "Wie lautet der Call für einen Reattack auf dasselbe Ziel?", "a": "<span class=\"qt\">(d) If the reattack is against the same target, the JTAC should state “Call sign, CONTINUE for a reattack, restrictions remain the same.”</span>", "src": [["jp3093", "p. V-48"]]},
   {"id": "m13-k5", "m": "m13", "q": "Wofür steht SALTR?", "a": "<span class=\"qt\">1. Size—number and type of equipment/personnel observed.<br><br>2. Activity—movement direction, stationary, dug-in.<br><br>3. Location.<br><br>4. Time.<br><br>5. Remarks—munitions expended, observed damage (number of tanks destroyed, number still active, and recommendation), mission number, and mission accomplished.</span>", "src": [["jp3093", "p. V-48"]]},
   {"id": "m13-k6", "m": "m13", "q": "Was gilt beim Melden von BDA?", "a": "<span class=\"qt\">(c) JTACs must ensure that BDA is accurate, and should not overestimate BDA, or report BDA that they cannot observe.</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m13-k7", "m": "m13", "q": "Was gibt der JTAC mindestens weiter, wenn kein BDA möglich ist?", "a": "<span class=\"qt\">If conditions preclude briefing BDA, at a minimum pass SUCCESSFUL, UNSUCCESSFUL, or UNKNOWN assessment to the aircraft and the controlling agency;</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m13-k8", "m": "m13", "q": "Mit welchem Format meldet die Besatzung Ergebnisse im Flug?", "a": "<span class=\"qt\">(f) Aircrew Responsibilities. Use the abbreviated USMTF INFLTREP (Figure V-12) to report CAS mission results.</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m13-k9", "m": "m13", "q": "Was ist BDA (NATO Agreed)?", "a": "<span class=\"qt\">battle damage assessment The timely and accurate assessment of damage resulting from the application of lethal or non-lethal force against an entity. (NATO Agreed)</span>", "src": [["ajp33", "p. LEX-7"]]},
   {"id": "m13-k10", "m": "m13", "q": "Welche Rolle können CAS-Controller beim Personnel Recovery übernehmen?", "a": "<span class=\"qt\">The various CAS controllers occupy a unique location in the operational area, which may allow them to be the first asset to realize that a personnel recovery isolating event has occurred. They should be prepared to assume on-scene commander (OSC) duties to report the event to higher authorities, locate the isolated personnel, and support them as necessary until relieved by another OSC or a rescue mission commander.</span>", "src": [["jp3093", "p. I-11"]]},
   {"id": "m14-k1", "m": "m14", "q": "Wo steht AJP-3.3 in der NATO-Doktrinhierarchie?", "a": "<span class=\"qt\">12. AJP-3.3 is subordinate to the keystone publication AJP-3. As a level-2 publication, the supporting and functional AJP-3.3 sits at the top of air and space operations doctrine, with subordinate level-3 documents and tactical publications covering further details.</span>", "src": [["ajp33", "p. xix"]]},
   {"id": "m14-k2", "m": "m14", "q": "Welche ATP nennt AJP-3.3 für CAS und AI?", "a": "<span class=\"qt\">13. Subordinate tactical publications, designated Allied tactical publications (ATPs), contain further supporting details in the form of tactics, techniques and procedures which include ATP-3.3.2.1, Tactics, Techniques and Procedures for Close Air Support and Air Interdiction, ATP-3.3.3.1, Air-Maritime Coordination Procedures (AMCP) and ATP-3.3.5.1, Joint Airspace Control Tactics, Techniques and Procedures.</span>", "src": [["ajp33", "p. xix"]]},
   {"id": "m14-k3", "m": "m14", "q": "Was sagt JP 3-09.3 zur Nutzung durch die NATO?", "a": "<span class=\"qt\">26. Planning for Multinational Operations a. NATO and partner nations have and continue to use JP 3-09.3, Close Air Support, as a basis for conducting CAS. See also Allied Joint Publication-3.3.2, Air Interdiction and Close Air Support, and Allied Tactical Publication-3.3.2.1(C), TTP for Close Air Support and Air Interdiction. Some differences still remain between US joint doctrine and US-ratified allied joint doctrine, but these differences are being addressed routinely.</span>", "src": [["jp3093", "p. III-127"]]},
   {"id": "m14-k4", "m": "m14", "q": "Was bedeutet * in ATP 1-02.1?", "a": "<span class=\"qt\">* Meaning differs from the North Atlantic Treaty Organization (NATO) brevity word.</span>", "src": [["atp1021", "p. 1"]]},
   {"id": "m14-k5", "m": "m14", "q": "Was bedeutet ** in ATP 1-02.1?", "a": "<span class=\"qt\">** Not a NATO brevity word.</span>", "src": [["atp1021", "p. 1"]]},
   {"id": "m14-k6", "m": "m14", "q": "Was ist ein Brevity Code (JP 3-09.3, Glossar)?", "a": "<span class=\"qt\">brevity code. A code word, which provides no security, that serves the sole purpose of shortening of messages rather than the concealment of their content. (Approved for incorporation into JP 1-02.)</span>", "src": [["jp3093", "p. GL-8"]]},
   {"id": "m14-k7", "m": "m14", "q": "Was ist friendly fire (NATO Agreed)?", "a": "<span class=\"qt\">friendly fire The employment of friendly weapons or munitions with intent to engage the enemy resulting in the unforeseen and unintentional injury or death of friendly personnel or destruction of property. (NATO Agreed)</span>", "src": [["ajp33", "p. LEX-8"]]},
   {"id": "m14-k8", "m": "m14", "q": "Wie beschreibt AJP-3.3 den TACP?", "a": "<span class=\"qt\">C.11 Tactical air control parties (TACP) are designed to provide air liaison to land forces and for the control of aircraft. They are staffed with air liaison officers and/or joint terminal attack controllers (JTAC) to conduct liaison and control functions.</span>", "src": [["ajp33", "p. C-3"]]}
  ].forEach(function (x) { L.push(x); });
})();
